const D = { offset: .18, gain: .35, energy: .5, density: .45, speed: 1, hue: 40, marks: .5, slur: .3, scale: 1, x: .5, y: .5, alpha: 92, act: 'run', style: 'offset', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp = (v, a, b) => v < a ? a : v > b ? b : v;
const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
const rgbv = (h, s, v) => {
  h = ((h % 360) + 360) % 360 / 60; const c = v * s, xx = c * (1 - Math.abs(h % 2 - 1)), m = v - c; let r, g2, b2;
  if (h < 1) { r = c; g2 = xx; b2 = 0; } else if (h < 2) { r = xx; g2 = c; b2 = 0; } else if (h < 3) { r = 0; g2 = c; b2 = xx; }
  else if (h < 4) { r = 0; g2 = xx; b2 = c; } else if (h < 5) { r = xx; g2 = 0; b2 = c; } else { r = c; g2 = 0; b2 = xx; }
  return [Math.round((r + m) * 255), Math.round((g2 + m) * 255), Math.round((b2 + m) * 255)];
};
const css = (h, s, v, a) => { const c = rgbv(h, s, v); return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; };

const W = width, H = height, u = Math.min(W, H), dc = drawingContext;
const of = clp(P.offset, 0, 1), gn = clp(P.gain, 0, 1), en = clp(P.energy, 0, 1);
const de = clp(P.density, 0, 1), mk = clp(P.marks, 0, 1), sl = clp(P.slur, 0, 1);
const sp = Math.max(.1, P.speed), sc = Math.max(.3, P.scale);
const st = P.style, hb = ((P.hue % 360) + 360) % 360, la = clp(P.alpha, 0, 100) / 100;
const prog = st === 'progressive', duo = st === 'duotone', news = st === 'newsprint', wet = st === 'wet_trap';

let stH = hb + 20, stS = .05, stV = .97, offM = 1, gnM = 1;
if (news) { stH = hb + 6; stS = .16; stV = .84; gnM = 1.7; offM = 1.3; }
else if (duo) { stH = hb + 12; stS = .07; stV = .95; offM = 2.1; }
else if (wet) { stH = hb + 4; stS = .12; stV = .88; gnM = 2.1; offM = 1.7; }
else if (prog) { stH = hb + 22; stS = .04; stV = .98; offM = 1.6; }
const stockCss = css(stH, stS, stV, 1);

// ---- buffers -----------------------------------------------------------------
const CW = Math.max(240, Math.min(900, Math.round(W * .5))), CH = Math.max(140, Math.round(CW * H / W));
if (!S.cap || S.cw !== CW || S.ch !== CH) {
  if (S.cap && S.cap.remove) S.cap.remove();
  if (S.tmp && S.tmp.remove) S.tmp.remove();
  if (S.out && S.out.remove) S.out.remove();
  S.cap = createGraphics(CW, CH); S.cap.pixelDensity(1);
  S.tmp = createGraphics(CW, CH); S.tmp.pixelDensity(1);
  S.out = createGraphics(CW, CH); S.out.pixelDensity(1);
  S.cw = CW; S.ch = CH;
}
const capC = S.cap.drawingContext.canvas, tmpC = S.tmp.drawingContext.canvas;
const cc = S.cap.drawingContext, tc = S.tmp.drawingContext, oc = S.out.drawingContext;

// grab the frame the layers below just composed
cc.globalCompositeOperation = 'copy'; cc.globalAlpha = 1;
try { cc.drawImage(dc.canvas, 0, 0, CW, CH); } catch (e) { }
cc.globalCompositeOperation = 'source-over';

// ---- act ---------------------------------------------------------------------
let creep = 1;
if (P.act === 'makeready') creep = .30 + .55 * (.5 + .5 * Math.sin(K.t * .0131 + 1.6));
else if (P.act === 'crash') creep = .7 + 1.9 * Math.pow(.5 + .5 * Math.sin(K.t * .0061 + .8 * Math.sin(K.t * .0023 + 2.1)), 2);
else creep = .72 + .62 * (.5 + .5 * Math.sin(K.t * .0089 + .5 * Math.sin(K.t * .0033 + 1.3)));
creep *= (.78 + .44 * K.intensity);

// ---- every plate wanders on its own orbit; none of them agree ----------------
const off = u * (.002 + of * .05) * offM * creep * (.7 + .6 * en);
const dirs = [], strs = [];
for (let k = 0; k < 4; k++) {
  const p0 = k * 1.9 + fr(k * 3 + 1) * 6.283;
  const ax = off * (.55 + .7 * fr(k * 5 + 2));
  dirs.push([
    ax * Math.sin(K.t * (.23 + k * .107) * sp + p0) + .5 * ax * Math.sin(K.t * (.41 + k * .073) * sp + p0 * 1.7),
    ax * Math.sin(K.t * (.29 + k * .091) * sp + p0 * 1.3) + .5 * ax * Math.sin(K.t * (.53 + k * .131) * sp + p0 * 2.1)
  ]);
  // plate stretch: the blanket creeps, so each separation prints a hair off-size
  strs.push((of * .008 + .0012) * offM * creep * Math.sin(K.t * (.19 + k * .061) * sp + p0 * .7));
}
const BOOST = ['rgb(0,255,255)', 'rgb(255,0,255)', 'rgb(255,255,0)'];
const NI = duo ? 2 : 3;
const sepx = CW / W, sepy = CH / H;
const build = k => {
  tc.globalCompositeOperation = 'copy'; tc.globalAlpha = 1;
  tc.drawImage(capC, 0, 0);
  tc.globalCompositeOperation = 'lighter';
  tc.fillStyle = BOOST[k]; tc.fillRect(0, 0, CW, CH);
  tc.globalCompositeOperation = 'source-over';
};
const lay = (k, dx, dy, sf) => {
  const s2 = 1 + sf;
  oc.drawImage(tmpC, dx + P.x * CW * (1 - s2), dy + P.y * CH * (1 - s2), CW * s2, CH * s2);
};

oc.globalCompositeOperation = 'source-over'; oc.globalAlpha = 1;
oc.fillStyle = stockCss; oc.fillRect(0, 0, CW, CH);
if (prog) {
  // the plates pulled apart on the bench: three progressives and the four-colour
  const pw = CW * .5, phh = CH * .5, gp = Math.min(pw, phh) * .04;
  const pos = [[0, 0], [pw, 0], [0, phh], [pw, phh]];
  for (let k = 0; k < 3; k++) {
    build(k);
    oc.globalCompositeOperation = 'multiply'; oc.globalAlpha = 1;
    oc.drawImage(tmpC, 0, 0, CW, CH, pos[k][0] + gp, pos[k][1] + gp, pw - 2 * gp, phh - 2 * gp);
  }
  for (let k = 0; k < 3; k++) {
    build(k);
    const d = dirs[k];
    oc.globalCompositeOperation = 'multiply'; oc.globalAlpha = 1;
    oc.drawImage(tmpC, 0, 0, CW, CH, pos[3][0] + gp + d[0] * sepx * .5, pos[3][1] + gp + d[1] * sepy * .5, pw - 2 * gp, phh - 2 * gp);
  }
  if (gn > .01) {
    oc.globalAlpha = clp(gn * .8 * gnM, 0, 1);
    oc.drawImage(capC, 0, 0, CW, CH, pos[3][0] + gp + dirs[3][0] * sepx * .5, pos[3][1] + gp + dirs[3][1] * sepy * .5, pw - 2 * gp, phh - 2 * gp);
  }
} else {
  const slk = Math.floor(fr(7) * NI) % NI;
  const sla = fr(8) * 6.283, slx = Math.cos(sla) * u * .006 * sl, sly = Math.sin(sla) * u * .006 * sl;
  for (let k = 0; k < NI; k++) {
    build(k);
    const d = dirs[k], dx = d[0] * sepx, dy = d[1] * sepy;
    oc.globalCompositeOperation = 'multiply'; oc.globalAlpha = 1;
    lay(k, dx, dy, strs[k]);
    if (sl > .02 && k === slk) {              // slur: this one smeared along the cylinder
      oc.globalAlpha = sl * .5;
      lay(k, dx + slx * sepx, dy + sly * sepy, strs[k]);
      lay(k, dx + slx * 2 * sepx, dy + sly * 2 * sepy, strs[k]);
      oc.globalAlpha = 1;
    }
    if (news) {                                // absorbent stock: the dot spreads
      oc.globalAlpha = .45;
      lay(k, dx + 1, dy + 1, strs[k]); lay(k, dx - 1, dy - 1, strs[k]);
      oc.globalAlpha = 1;
    }
  }
  if (gn > .01) {                              // the key plate, and with it the dot gain
    oc.globalCompositeOperation = 'multiply';
    oc.globalAlpha = clp(gn * .85 * gnM * (.8 + .35 * K.swell), 0, 1);
    const s2 = 1 + strs[3];
    oc.drawImage(capC, dirs[3][0] * sepx + P.x * CW * (1 - s2), dirs[3][1] * sepy + P.y * CH * (1 - s2), CW * s2, CH * s2);
    oc.globalAlpha = 1;
  }
}
// printed black is never a void — the stock keeps scattering light back through the film
oc.globalCompositeOperation = 'screen';
oc.globalAlpha = clp(.10 + gn * .22 * gnM, 0, 1);
oc.fillStyle = css(stH, stS * .6, stV * .34, 1);
oc.fillRect(0, 0, CW, CH);
oc.globalCompositeOperation = 'source-over';
oc.globalAlpha = 1;

// ---- to the sheet ------------------------------------------------------------
const oldA = dc.globalAlpha;
blendMode(BLEND); noStroke();
dc.globalAlpha = la;
dc.drawImage(S.out.drawingContext.canvas, 0, 0, W, H);

// cylinder banding — the ink film is never even around the roller
const nb = 8 + Math.round(de * 20);
const bph = K.t * .047 * sp + .4 * Math.sin(K.t * .017 + 1.1) + .15 * Math.sin(K.t * .039);
blendMode(MULTIPLY);
const bh = H / nb;
for (let k = 0; k < nb; k++) {
  const a = Math.pow(.5 + .5 * Math.sin(k * 2.1 / sc + bph * 6.283), 2) * (.05 + .18 * en);
  if (a < .004) continue;
  dc.globalAlpha = la * a;
  dc.fillStyle = css(hb + 200, .3, .18, 1);
  dc.fillRect(0, k * bh - 1, W, bh + 2);
}
blendMode(BLEND);

// hickeys — a fleck of dried ink on the blanket prints a hole with a ring round it
const nh = Math.round(de * 7);
for (let k = 0; k < nh; k++) {
  const q = j => fr(k * 11.3 + j * 2.1 + 13);
  const hx = (q(1) + .04 * Math.sin(K.t * .011 + k)) * W, hy = (q(2) + .03 * Math.sin(K.t * .013 + k * 2.2)) * H;
  const hr = u * (.004 + .014 * q(3)) * sc;
  dc.globalAlpha = la * (.4 + .5 * en);
  dc.fillStyle = css(stH, stS, stV, 1);
  dc.beginPath(); dc.arc(hx, hy, hr, 0, 6.2832); dc.fill();
  dc.globalAlpha = la * (.5 + .4 * en);
  dc.fillStyle = css(hb + 200, .5, .16, 1);
  dc.beginPath(); dc.arc(hx, hy, hr * .45, 0, 6.2832); dc.fill();
}

// ---- register targets and the colour bar, each printed by its own plate -------
if (mk > .02) {
  const INK = [[190, 100, .86], [318, 96, .88], [52, 96, .98], [30, 10, .10]];
  const ms = u * .022 * sc * (.5 + mk);
  blendMode(MULTIPLY);
  dc.lineWidth = Math.max(1, u * .0022 * sc);
  for (let k = 0; k < (duo ? 2 : 4); k++) {
    const d = dirs[k];
    dc.strokeStyle = css(INK[k][0], INK[k][1] / 100, INK[k][2], 1);
    dc.globalAlpha = la * mk * .9;
    for (let m = 0; m < 4; m++) {
      const mx = [W * .5, W * .5, ms * 1.5, W - ms * 1.5][m] + d[0];
      const my = [ms * 1.5, H - ms * 1.5, H * .5, H * .5][m] + d[1];
      dc.beginPath();
      dc.moveTo(mx - ms, my); dc.lineTo(mx + ms, my);
      dc.moveTo(mx, my - ms); dc.lineTo(mx, my + ms);
      dc.stroke();
      dc.beginPath(); dc.arc(mx, my, ms * .55, 0, 6.2832); dc.stroke();
    }
  }
  if (mk > .22 && !prog) {
    const bar = [[190, 100, .86], [318, 96, .88], [52, 96, .98], [30, 10, .10], [190, 55, .93], [318, 52, .94], [52, 50, 1], [30, 8, .5], [244, 78, .5], [352, 92, .74], [150, 92, .6], [30, 12, .3]];
    const bw = W / bar.length, bhh = u * .018 * sc * (.4 + mk);
    const d = dirs[3];
    dc.globalAlpha = la * mk * .92;
    for (let k = 0; k < bar.length; k++) {
      dc.fillStyle = css(bar[k][0], bar[k][1] / 100, bar[k][2], 1);
      dc.fillRect(k * bw + d[0], H - bhh - u * .004 + d[1], bw * .9, bhh);
    }
  }
  blendMode(BLEND);
}

dc.globalAlpha = oldA;
blendMode(BLEND);
dc.shadowBlur = 0;
